package ubxbin

import (
	"encoding/hex"
	"testing"
)

// rxmRawxF9T is a UBX-RXM-RAWX packet captured from an F9T receiver
// with 65 measurements at GPS week 2397.
const rxmRawxF9T = ""

func TestRxmRawx(t *testing.T) {
	pkt, err := hex.DecodeString(rxmRawxF9T)
	if err != nil {
		t.Fatalf("decode hex: %v", err)
	}
	msg, err := ParseMsg(string(pkt))
	if err != nil {
		t.Fatalf("ParseMsg: %v", err)
	}
	rawx, ok := msg.(*RxmRawx)
	if !ok {
		t.Fatalf("got %T, want *RxmRawx", msg)
	}
	if rawx.Version != 1 {
		t.Errorf("Version = %d, want 1", rawx.Version)
	}
	if rawx.Week != 2397 {
		t.Errorf("Week = %d, want 2397", rawx.Week)
	}
	if rawx.LeapS != 18 {
		t.Errorf("LeapS = %d, want 18", rawx.LeapS)
	}
	if rawx.NumMeas != 65 || len(rawx.Meas) != 65 {
		t.Errorf("NumMeas = %d, len(Meas) = %d, want 65, 65", rawx.NumMeas, len(rawx.Meas))
	}
	if rawx.RecStat&RxmRawxLeapSec == 0 {
		t.Errorf("RecStat = 0x%02x, want LeapSec bit set", rawx.RecStat)
	}
	for i, m := range rawx.Meas {
		if m.GNSSID > NavIC {
			t.Errorf("Meas[%d].GNSSID = %d out of range", i, m.GNSSID)
		}
		if m.SVID == 0 {
			t.Errorf("Meas[%d].SVID = 0", i)
		}
		if m.PrMes < 15e6 || m.PrMes > 45e6 {
			t.Errorf("Meas[%d].PrMes = %g, want plausible GNSS pseudorange", i, m.PrMes)
		}
		if m.CNO == 0 || m.CNO > 70 {
			t.Errorf("Meas[%d].CNO = %d, want plausible C/N0", i, m.CNO)
		}
		if m.TrkStat&RxmRawxPrValid == 0 {
			t.Errorf("Meas[%d].TrkStat = 0x%02x, want PrValid set", i, m.TrkStat)
		}
	}
}

func TestRxmRawxUnknownVersion(t *testing.T) {
	payload := make([]byte, 16)
	payload[13] = 0x00 // version != 1
	packet := []byte{Sync1, Sync2, 0x02, 0x15, 0x10, 0x00}
	packet = append(packet, payload...)
	ckA, ckB := Checksum(packet[2:])
	packet = append(packet, ckA, ckB)
	msg, err := ParseMsg(string(packet))
	if err != nil {
		t.Fatalf("ParseMsg: %v", err)
	}
	if _, ok := msg.(*UnknownMsg); !ok {
		t.Fatalf("got %T, want *UnknownMsg", msg)
	}
}
